import { existsSync, readFileSync } from "node:fs";
import path from "node:path";

import { describe, expect, it } from "vitest";

const pollerDir = path.resolve(import.meta.dirname, "..");
const pkg = JSON.parse(readFileSync(path.join(pollerDir, "package.json"), "utf8")) as {
  scripts: { build: string };
  dependencies: Record<string, string>;
};

/** Provided by the Functions host or generated by Prisma, so never a dependency of this package. */
const PROVIDED_AT_RUNTIME = new Set(["@azure/functions-core", ".prisma/client"]);

const externals = [...pkg.scripts.build.matchAll(/--external:(\S+)/g)]
  .map((m) => m[1] ?? "")
  .filter((name) => !PROVIDED_AT_RUNTIME.has(name));

describe("poller build", () => {
  it("names at least one external the bundle leaves to node_modules", () => {
    expect(externals.length).toBeGreaterThan(0);
  });

  it("declares every external as a runtime dependency so dist/ can resolve it on the Function App", () => {
    for (const name of externals) {
      expect(pkg.dependencies, `${name} is --external but not in dependencies`).toHaveProperty(name);
    }
  });

  it("resolves every external from where dist/index.js will run", () => {
    // Node's lookup, by hand: `pnpm run` puts the hidden .pnpm/node_modules on NODE_PATH, which
    // would make require.resolve pass here and fail on the Function App.
    const resolvable = (name: string) => {
      for (let dir = path.join(pollerDir, "dist"); ; dir = path.dirname(dir)) {
        if (existsSync(path.join(dir, "node_modules", name, "package.json"))) return true;
        if (dir === path.dirname(dir)) return false;
      }
    };
    for (const name of externals) {
      expect(resolvable(name), `${name} does not resolve from poller/dist`).toBe(true);
    }
  });
});
